export const academyLessons = academyModules
  .flatMap((module) => module.lessons)
  .sort((a, b) => a.order - b.order);

/**
 * Flat search index used by the dashboard. Keep this derived from the canonical
 * curriculum so search and the Academy can never drift apart.
 */
export type AcademyTopic = {
  id: string;
  title: string;
  summary: string;
  trackNumber: string;
  trackTitle: string;
  concepts: string[];
  lessonOrder: number;
};

export const allAcademyTopics: AcademyTopic[] = academyModules.flatMap((module) =>
  module.lessons.map((lesson) => ({
    id: lesson.id,
    title: lesson.title,
    summary: lesson.summary,
    trackNumber: module.number,
    trackTitle: module.title,
    concepts: lesson.concepts.map((concept) => concept.term),
    lessonOrder: lesson.order,
  })),
);
